// ─────────────────────────────────────────────────────────────────────────
//  01 · closest exception handler★★☆
//  concepts: class hierarchy · handler resolution · problem details
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.function.*;

class Exercise {

    record Problem(int status, String title, String detail) {}
    static class NotFoundException extends RuntimeException { NotFoundException(String m) { super(m); } }
    static class OrderNotFoundException extends NotFoundException { OrderNotFoundException(long id) { super("order " + id + " not found"); } }
    static class ConflictException extends RuntimeException { ConflictException(String m) { super(m); } }

    static final Problem INTERNAL = new Problem(500, "Internal Server Error", null);

    /** The handler for the closest type in the exception's hierarchy, else a generic 500 problem. */
    static Problem resolve(Throwable error, Map<Class<? extends Throwable>, Function<Throwable, Problem>> handlers) {
        if (error == null) return INTERNAL;
        for (Class<?> c = error.getClass(); c != null; c = c.getSuperclass()) {
            var handler = handlers.get(c);
            if (handler != null) return handler.apply(error);
        }
        return INTERNAL;
    }

    static Map<Class<? extends Throwable>, Function<Throwable, Problem>> handlers() {
        var m = new HashMap<Class<? extends Throwable>, Function<Throwable, Problem>>();
        m.put(Exception.class, e -> new Problem(500, "Internal Server Error", null));
        m.put(NotFoundException.class, e -> new Problem(404, "Not Found", e.getMessage()));
        m.put(ConflictException.class, e -> new Problem(409, "Conflict", e.getMessage()));
        return m;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a subclass uses its closest handler", () -> eq(resolve(new OrderNotFoundException(42), handlers()), new Problem(404, "Not Found", "order 42 not found")));
        test("an exact match is used", () -> eq(resolve(new ConflictException("stale version"), handlers()).status(), 409));
        test("unknown exceptions fall back to the Exception handler", () -> eq(resolve(new IllegalStateException("bug"), handlers()), new Problem(500, "Internal Server Error", null)));
        test("no handler at all gives a generic 500 (boundary)", () -> eq(resolve(new AssertionError("x"), Map.of()), new Problem(500, "Internal Server Error", null)));
        test("a null error is a generic 500", () -> eq(resolve(null, handlers()).status(), 500));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

